279.             <label for="full-name">
280.               Full name <span class="required-marker" aria-hidden="true">*</span>
281.             </label>
282.             <input
283.               id="full-name"
284.               name="full-name"
285.               type="text"
286.               autocomplete="name"
287.               required
288.             >
289.           </div>
290. 
291.           <div class="form-field">
292.             <label for="email">
293.               Email address <span class="required-marker" aria-hidden="true">*</span>
294.             </label>
295.             <input
296.               id="email"
297.               name="email"
298.               type="email"
299.               autocomplete="email"
300.               required
301.             >
302.           </div>
303. 
304.           <div class="form-field">
305.             <label for="phone">Phone number <span class="optional">(optional)</span></label>
306.             <input
307.               id="phone"
308.               name="phone"
309.               type="tel"
310.               autocomplete="tel"
311.               aria-describedby="phone-help"
312.             >
313.             <p class="helper-text" id="phone-help">Use digits, spaces, dashes, or parentheses, such as (555) 123-4567.</p>
314.           </div>
315. 
316.           <div class="form-actions">
317.             <button type="submit">Send request</button>
318.             <p class="form-status" id="form-status" aria-live="polite"></p>
319.           </div>
320.         </form>
