324.     <script>
325.       const form = document.querySelector("#support-form");
326.       const statusMessage = document.querySelector("#form-status");
327.       const fields = [
328.         {
329.           id: "full-name",
330.           message: "Error: Enter your full name."
331.         },
332.         {
333.           id: "email",
334.           message: "Error: Enter a valid email address, such as name@example.com."
335.         }
336.       ];
337. 
338.       function removeError(input) {
339.         const error = document.querySelector(`#${input.id}-error`);
340.         input.removeAttribute("aria-invalid");
341. 
342.         if (error) {
343.           error.remove();
344.         }
345. 
346.         const describedBy = (input.getAttribute("aria-describedby") || "")
347.           .split(" ")
348.           .filter((id) => id && id !== `${input.id}-error`)
349.           .join(" ");
350. 
351.         if (describedBy) {
352.           input.setAttribute("aria-describedby", describedBy);
353.         } else {
354.           input.removeAttribute("aria-describedby");
355.         }
356.       }
357. 
358.       function showError(input, message) {
359.         removeError(input);
360. 
361.         const error = document.createElement("p");
362.         error.className = "error-message";
363.         error.id = `${input.id}-error`;
364.         error.textContent = message;
365.         input.insertAdjacentElement("afterend", error);
366. 
367.         const describedBy = new Set(
368.           (input.getAttribute("aria-describedby") || "").split(" ").filter(Boolean)
369.         );
370.         describedBy.add(error.id);
371.         input.setAttribute("aria-describedby", [...describedBy].join(" "));
372.         input.setAttribute("aria-invalid", "true");
373.       }
