384.         const input = document.getElementById(id);
385.         input.addEventListener("input", () => {
386.           if (isValid(input)) {
387.             removeError(input);
388.           }
389.         });
390.       });
391. 
392.       form.addEventListener("submit", (event) => {
393.         event.preventDefault();
394.         statusMessage.textContent = "";
395. 
396.         const invalidFields = fields.filter(({ id, message }) => {
397.           const input = document.getElementById(id);
398. 
399.           if (isValid(input)) {
400.             removeError(input);
401.             return false;
402.           }
403. 
404.           showError(input, message);
405.           return true;
406.         });
407. 
408.         if (invalidFields.length > 0) {
409.           document.getElementById(invalidFields[0].id).focus();
410.           return;
411.         }
412. 
