const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');
const axe = require('axe-core');

(async () => {
  let browser;
  try {
    browser = await chromium.launch();
  } catch (error) {
    console.error(error.message);
    process.exit(86);
  }

  const page = await browser.newPage();
  await page.goto(`file://${path.resolve('index.html')}`);
  await page.addScriptTag({ content: axe.source });

  async function audit(label) {
    const result = await page.evaluate(async () => window.axe.run(document));
    const wcag = result.violations.filter((v) => !v.tags.includes('best-practice'));
    const bestPractice = result.violations.filter((v) => v.tags.includes('best-practice'));
    return {
      label,
      wcag: wcag.map((v) => ({
        id: v.id,
        impact: v.impact,
        targets: v.nodes.map((n) => n.target)
      })),
      bestPractice: bestPractice.map((v) => ({
        id: v.id,
        impact: v.impact,
        targets: v.nodes.map((n) => n.target)
      }))
    };
  }

  const initial = await audit('initial');
  await page.click('button[type="submit"]');
  const submitted = await audit('submitted-empty');
  await browser.close();

  const results = [initial, submitted];
  console.log(JSON.stringify(results, null, 2));
  if (results.some((r) => r.wcag.length > 0)) process.exit(1);
})();
