   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>

     <main id="main-content">
       <section class="support-card" aria-labelledby="support-title">
         <div class="card-header">
           <p class="eyebrow">Support</p>
           <h1 id="support-title">Contact our team</h1>
           <p class="intro">
             Share your contact details and our support team will get back to you with the next steps.
           </p>
         </div>

         <form id="support-form" novalidate>
           <p class="required-note">
             Fields marked with <span class="required-marker" aria-hidden="true">*</span> are required.
           </p>

           <div class="form-field">
             <label for="full-name">
               Full name <span class="required-marker" aria-hidden="true">*</span>
             </label>
             <input
               id="full-name"
               name="full-name"
               type="text"
               autocomplete="name"
               required
             >
           </div>

           <div class="form-field">
             <label for="email">
               Email address <span class="required-marker" aria-hidden="true">*</span>
             </label>
             <input
               id="email"
               name="email"
               type="email"
               autocomplete="email"
               required
             >
           </div>

           <div class="form-field">
             <label for="phone">Phone number <span class="optional">(optional)</span></label>
             <input
               id="phone"
               name="phone"
               type="tel"
               autocomplete="tel"
               aria-describedby="phone-help"
             >
             <p class="helper-text" id="phone-help">Use digits, spaces, dashes, or parentheses, such as (555) 123-4567.</p>
           </div>

           <div class="form-actions">
             <button type="submit">Send request</button>
             <p class="form-status" id="form-status" aria-live="polite"></p>
           </div>
         </form>
       </section>
     </main>

     <script>
       const form = document.querySelector("#support-form");
       const statusMessage = document.querySelector("#form-status");
       const fields = [
         {
           id: "full-name",
           message: "Error: Enter your full name."
         },
         {
           id: "email",
           message: "Error: Enter a valid email address, such as name@example.com."
         }
       ];

       function removeError(input) {
         const error = document.querySelector(`#${input.id}-error`);
         input.removeAttribute("aria-invalid");

         if (error) {
           error.remove();
         }

         const describedBy = (input.getAttribute("aria-describedby") || "")
           .split(" ")
           .filter((id) => id && id !== `${input.id}-error`)
           .join(" ");

         if (describedBy) {
           input.setAttribute("aria-describedby", describedBy);
         } else {
           input.removeAttribute("aria-describedby");
         }
       }

       function showError(input, message) {
         removeError(input);

         const error = document.createElement("p");
         error.className = "error-message";
         error.id = `${input.id}-error`;
         error.textContent = message;
         input.insertAdjacentElement("afterend", error);

         const describedBy = new Set(
           (input.getAttribute("aria-describedby") || "").split(" ").filter(Boolean)
         );
         describedBy.add(error.id);
         input.setAttribute("aria-describedby", [...describedBy].join(" "));
         input.setAttribute("aria-invalid", "true");
       }

       function isValid(input) {
         if (input.type === "email") {
           return input.validity.valid;
         }

         return input.value.trim().length > 0;
       }

       fields.forEach(({ id }) => {
         const input = document.getElementById(id);
         input.addEventListener("input", () => {
           if (isValid(input)) {
             removeError(input);
           }
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         statusMessage.textContent = "";

         const invalidFields = fields.filter(({ id, message }) => {
           const input = document.getElementById(id);

           if (isValid(input)) {
             removeError(input);
             return false;
           }

           showError(input, message);
           return true;
         });

         if (invalidFields.length > 0) {
           document.getElementById(invalidFields[0].id).focus();
           return;
         }

         form.reset();
         fields.forEach(({ id }) => removeError(document.getElementById(id)));
         statusMessage.textContent = "Thanks. Your support request is ready to send.";
       });
     </script>
